package dev.disc;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.phys.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.nbt.CompoundTag;
public class DiscGameTests implements FabricGameTest {
 private static ServerPlayer player(GameTestHelper h){
  var p=new ServerPlayer(h.getLevel().getServer(),h.getLevel(),new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"disc-test"),net.minecraft.server.level.ClientInformation.createDefault());
  var c=new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);new io.netty.channel.embedded.EmbeddedChannel(c);h.getLevel().getServer().getPlayerList().placeNewPlayer(c,p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));
  p.setPos(Vec3.atBottomCenterOf(h.absolutePos(new BlockPos(1,32,1))));p.setNoGravity(true);for(int z=-32;z<=48;z+=16)h.getLevel().getChunk(BlockPos.containing(p.position().add(0,0,z)));return p;
 }
 private static ThrowingDiscEntity disc(GameTestHelper h,ServerPlayer p){var d=new ThrowingDiscEntity(ModEntities.DISC,h.getLevel());d.launch(p,new ItemStack(ModItems.get(DiscTier.IRON)),2);h.getLevel().addFreshEntity(d);return d;}
 private static void returning(ThrowingDiscEntity d){var tag=new CompoundTag();d.addAdditionalSaveData(tag);tag.putBoolean("Returning",true);d.readAdditionalSaveData(tag);}
 @GameTest(template=EMPTY_STRUCTURE) public void completeReturn(GameTestHelper h){var p=player(h);var d=disc(h,p);d.setDeltaMovement(new Vec3(0,0,1.25));for(int i=0;i<150&&!d.isRemoved();i++)d.tick();h.assertTrue(d.isRemoved()&&p.getInventory().getItem(2).is(ModItems.get(DiscTier.IRON)),"Flight returns original item");h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE) public void fourTiersAndDurability(GameTestHelper h){h.assertTrue(DiscTier.values().length==4,"Copper excluded");int[] dur={125,16,780,1015};float[] dmg={6,5,7.5F,8.5F};double[] range={16,18,19,21};for(var t:DiscTier.values()){var stack=new ItemStack(ModItems.get(t));h.assertTrue(stack.getMaxDamage()==dur[t.ordinal()]&&t.damage==dmg[t.ordinal()]&&t.range==range[t.ordinal()],"Reference tuning preserved");h.assertTrue(stack.get(net.minecraft.core.component.DataComponents.ATTRIBUTE_MODIFIERS).modifiers().stream().anyMatch(e->e.attribute().equals(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE)&&Math.abs(e.modifier().amount()-(t.melee-1))<0.001),"Melee attribute installed");}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE) public void enchantmentBooksAndExclusivity(GameTestHelper h){var p=player(h);p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);String[] names={"homing","curve","range","keen_edge","harvest"};int[] levels={4,2,5,3,1};for(int i=0;i<names.length;i++){var e=DiscEnchantments.get(names[i]);h.assertTrue(e.getMaxLevel()==levels[i],"Enchantment cap");var anvil=new net.minecraft.world.inventory.AnvilMenu(0,p.getInventory());anvil.getSlot(0).set(new ItemStack(ModItems.get(DiscTier.IRON)));anvil.getSlot(1).set(EnchantedBookItem.createForEnchantment(new net.minecraft.world.item.enchantment.EnchantmentInstance(e,1)));anvil.createResult();h.assertTrue(!anvil.getSlot(2).getItem().isEmpty(),"Book applies: "+names[i]);}h.assertTrue(!DiscEnchantments.get("curve").isCompatibleWith(DiscEnchantments.get("homing")),"Steering exclusive");h.assertTrue(!net.minecraft.core.registries.BuiltInRegistries.ENCHANTMENT.containsKey(ThrowingDiscMod.id("ricochet")),"No Ricochet");h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE) public void persistence(GameTestHelper h){var p=player(h);var d=disc(h,p);d.getItem().set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Keep me"));d.getItem().enchant(DiscEnchantments.get("harvest"),1);var tag=new CompoundTag();d.addAdditionalSaveData(tag);var copy=new ThrowingDiscEntity(ModEntities.DISC,h.getLevel());copy.readAdditionalSaveData(tag);h.assertTrue(copy.throwerId().equals(p.getUUID())&&ItemStack.matches(copy.getItem(),d.getItem()),"Complete item survives save");d.discard();copy.catchBy(p);h.assertTrue(p.getInventory().getItem(2).is(ModItems.get(DiscTier.IRON)),"Origin slot preserved");h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE) public void nearbyReturnPhasesButOutboundBounces(GameTestHelper h){var p=player(h);var block=BlockPos.containing(p.position().add(0,1,2));h.getLevel().setBlock(block,Blocks.STONE.defaultBlockState(),3);var d=disc(h,p);d.setPos(Vec3.atCenterOf(block).add(0,0,-1));d.setDeltaMovement(new Vec3(0,0,1.25));d.tick();h.assertTrue(d.getDeltaMovement().z<0,"Outbound collides near owner");d.discard();d=disc(h,p);returning(d);d.setPos(Vec3.atCenterOf(block).add(0,0,1));d.setDeltaMovement(new Vec3(0,0,-1.25));d.tick();h.assertTrue(d.getZ()<block.getZ()+1&&d.getDeltaMovement().z<0,"Nearby return phases");d.catchBy(p);h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE) public void distantReturnAndNinthBounce(GameTestHelper h){var p=player(h);var b=BlockPos.containing(p.position().add(0,1,12));h.getLevel().setBlock(b,Blocks.STONE.defaultBlockState(),3);var d=disc(h,p);returning(d);d.setPos(Vec3.atCenterOf(b).add(0,0,1));d.setDeltaMovement(new Vec3(0,0,-1.25));d.tick();h.assertTrue(d.getDeltaMovement().z>0,"Return outside eight blocks collides");d.discard();d=disc(h,p);var tag=new CompoundTag();d.addAdditionalSaveData(tag);tag.putInt("Bounces",8);d.readAdditionalSaveData(tag);d.setPos(Vec3.atCenterOf(b).add(0,0,-1));d.setDeltaMovement(new Vec3(0,0,1.25));d.tick();tag=new CompoundTag();d.addAdditionalSaveData(tag);h.assertTrue(tag.getInt("Bounces")>=9&&!tag.getBoolean("Returning"),"Ninth bounce remains outbound");d.catchBy(p);h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE) public void harvest(GameTestHelper h){var p=player(h);var b=BlockPos.containing(p.position().add(0,1,2));h.getLevel().setBlock(b.below(),Blocks.FARMLAND.defaultBlockState(),3);h.getLevel().setBlock(b,Blocks.WHEAT.defaultBlockState().setValue(net.minecraft.world.level.block.CropBlock.AGE,7),3);var d=disc(h,p);d.getItem().enchant(DiscEnchantments.get("harvest"),1);d.setPos(Vec3.atCenterOf(b).add(0,0,-1));d.setDeltaMovement(new Vec3(0,0,2));d.tick();h.assertTrue(h.getLevel().getBlockState(b).isAir(),"Mature crop harvested");h.assertTrue(!h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(b).inflate(2)).isEmpty(),"Crop drops");d.discard();h.getLevel().setBlock(b,Blocks.WHEAT.defaultBlockState(),3);d=disc(h,p);d.getItem().enchant(DiscEnchantments.get("harvest"),1);d.setPos(Vec3.atCenterOf(b).add(0,0,-1));d.setDeltaMovement(new Vec3(0,0,2));d.tick();h.assertTrue(h.getLevel().getBlockState(b).is(Blocks.WHEAT),"Young crop preserved");d.catchBy(p);h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE) public void dispenserReusesDisc(GameTestHelper h){var pos=h.absolutePos(new BlockPos(1,32,1));for(int z=-32;z<=48;z+=16)h.getLevel().getChunk(pos.offset(0,0,z));var state=Blocks.DISPENSER.defaultBlockState().setValue(net.minecraft.world.level.block.DispenserBlock.FACING,net.minecraft.core.Direction.SOUTH);h.getLevel().setBlock(pos,state,3);var inv=(net.minecraft.world.level.block.entity.DispenserBlockEntity)h.getLevel().getBlockEntity(pos);inv.setItem(2,new ItemStack(ModItems.get(DiscTier.IRON)));for(int attempt=0;attempt<2;attempt++){state.tick(h.getLevel(),pos,h.getLevel().random);var flights=h.getLevel().getEntitiesOfClass(ThrowingDiscEntity.class,new AABB(pos).inflate(2),e->!e.isRemoved());h.assertTrue(flights.size()==1&&inv.getItem(2).isEmpty(),"Dispenser transfers one item");var d=flights.get(0);for(int tick=0;tick<200&&!d.isRemoved();tick++)d.tick();h.assertTrue(d.isRemoved()&&inv.getItem(2).is(ModItems.get(DiscTier.IRON))&&inv.getItem(2).getDamageValue()==attempt+1,"Reusable return with wear");}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE) public void crafting(GameTestHelper h){var menu=new net.minecraft.world.inventory.AbstractContainerMenu(null,0){public ItemStack quickMoveStack(net.minecraft.world.entity.player.Player p,int i){return ItemStack.EMPTY;}public boolean stillValid(net.minecraft.world.entity.player.Player p){return true;}};var input=new net.minecraft.world.inventory.TransientCraftingContainer(menu,3,3);Item[] ingredients={Items.IRON_INGOT,Items.GOLD_INGOT,Items.DIAMOND};for(int i=0;i<ingredients.length;i++){input.clearContent();for(int slot:new int[]{1,3,5,7})input.setItem(slot,new ItemStack(ingredients[i]));var recipe=h.getLevel().getRecipeManager().getRecipeFor(net.minecraft.world.item.crafting.RecipeType.CRAFTING,input,h.getLevel()).orElseThrow();h.assertTrue(recipe.value().assemble(input,h.getLevel().registryAccess()).is(ModItems.get(DiscTier.values()[i])),"Recipe output");}h.succeed();}
}
